"""ORA — icônes iOS 26/27 redessinées d'après capture (formes fidèles, palette ORA monochrome ; logo Apple affiché dans les tutos qui montrent un iPhone). Dict I : nom -> <svg>."""
import math
B='#FAFAFA'; G1='#d6d6d6'; G2='#a8a8a8'; G3='#7a7a7a'; G4='#4a4a4a'; N='#141414'
def svg(inner): return f'<svg viewBox="0 0 100 100" width="100%" height="100%">{inner}</svg>'
I={}
I['facetime']=svg(f'<rect x="13" y="31" width="47" height="38" rx="10" fill="{B}"/><path d="M63 44 L84 32.5 Q88 30.5 88 35 V65 Q88 69.5 84 67.5 L63 56 Z" fill="{B}"/>')
pet=''.join(f'<ellipse cx="50" cy="29" rx="11.5" ry="19" transform="rotate({k*45} 50 50)" fill="{c}" fill-opacity=".82"/>' for k,c in enumerate([B,G1,G2,G3,G2,G1,B,G1]))
I['photos']=svg(pet+f'<circle cx="50" cy="50" r="4.5" fill="{N}"/>')
I['camera']=svg(f'<circle cx="50" cy="50" r="36" fill="{G2}"/><circle cx="50" cy="50" r="31" fill="#1c1c1c"/><circle cx="50" cy="50" r="24" fill="#2c2c2c"/><circle cx="50" cy="50" r="15" fill="#0c0c0c"/><circle cx="50" cy="50" r="9" fill="#262626"/><ellipse cx="42" cy="41" rx="6" ry="3.5" fill="{B}" fill-opacity=".7" transform="rotate(-35 42 41)"/><circle cx="58" cy="58" r="2.2" fill="{B}" fill-opacity=".4"/>')
I['mail']=svg(f'<rect x="14" y="27" width="72" height="47" rx="9" fill="{B}"/><path d="M17 31 L50 56 L83 31" fill="none" stroke="#9a9a9a" stroke-width="3.2" stroke-linejoin="round"/>')
dots=''.join(f'<circle cx="{x}" cy="34" r="1.6" fill="{G3}"/>' for x in range(8,96,6))
I['notes']=svg(f'<rect x="0" y="0" width="100" height="29" fill="{G1}"/>{dots}<line x1="12" y1="56" x2="88" y2="56" stroke="{G3}" stroke-width="3"/><line x1="12" y1="74" x2="88" y2="74" stroke="{G3}" stroke-width="3"/>')
I['rappels']=svg(''.join(f'<circle cx="25" cy="{y}" r="7.5" fill="{c}"/><line x1="40" y1="{y}" x2="84" y2="{y}" stroke="{G3}" stroke-width="3"/>' for y,c in [(31,B),(50,G2),(69,G1)]))
ticks=''.join(f'<line x1="{50+37*math.sin(math.radians(a)):.1f}" y1="{50-37*math.cos(math.radians(a)):.1f}" x2="{50+(33 if a%30==0 else 35)*math.sin(math.radians(a)):.1f}" y2="{50-(33 if a%30==0 else 35)*math.cos(math.radians(a)):.1f}" stroke="{B}" stroke-width="{1.6 if a%30==0 else .8}"/>' for a in range(0,360,6))
nums=''.join(f'<text x="{50+26*math.sin(math.radians(a)):.1f}" y="{50-26*math.cos(math.radians(a))+4.5:.1f}" font-size="12" font-family="-apple-system,Jost,sans-serif" font-weight="500" fill="{B}" text-anchor="middle">{n}</text>' for a,n in [(0,12),(90,3),(180,6),(270,9)])
I['horloge']=svg(f'<circle cx="50" cy="50" r="40" fill="#0b0b0b" stroke="{G4}" stroke-width="1"/>{ticks}{nums}<line x1="50" y1="50" x2="38" y2="42" stroke="{B}" stroke-width="3.2" stroke-linecap="round"/><line x1="50" y1="50" x2="72" y2="48" stroke="{B}" stroke-width="2.4" stroke-linecap="round"/><line x1="44" y1="36" x2="58" y2="74" stroke="{G2}" stroke-width="1.2"/><circle cx="50" cy="50" r="2.6" fill="{B}"/>')
I['podcasts']=svg(f'<circle cx="50" cy="50" r="38" fill="{G4}"/><path d="M30 60 A22 22 0 1 1 70 60" fill="none" stroke="{B}" stroke-width="5" stroke-linecap="round"/><path d="M39 56 A12 12 0 1 1 61 56" fill="none" stroke="{B}" stroke-width="4.5" stroke-linecap="round"/><circle cx="50" cy="47" r="7" fill="{B}"/><rect x="45" y="57" width="10" height="24" rx="5" fill="{B}"/>')
I['appstore']=svg(f'<g stroke="{B}" stroke-width="7.5" stroke-linecap="round"><line x1="35" y1="74" x2="56" y2="30"/><line x1="65" y1="74" x2="44" y2="30"/><line x1="25" y1="61" x2="75" y2="61"/></g>')
I['plans']=svg(f'<rect x="0" y="0" width="100" height="100" fill="#1d1d1d"/><path d="M66 -5 A40 40 0 0 1 105 30" fill="none" stroke="{G4}" stroke-width="5"/><path d="M76 -5 A30 30 0 0 1 105 20" fill="none" stroke="{G4}" stroke-width="4"/><rect x="40" y="-5" width="18" height="110" fill="{G2}" transform="rotate(-8 50 50)"/><circle cx="50" cy="58" r="21" fill="{B}"/><circle cx="50" cy="58" r="16" fill="{G1}"/><path d="M50 46 L59 68 L50 63 L41 68 Z" fill="{N}"/>')
I['sante']=svg(f'<path d="M50 80 C24 63 16 50 16 38 C16 27 24 20 33 20 C41 20 47 25 50 31 C53 25 59 20 67 20 C76 20 84 27 84 38 C84 50 76 63 50 80 Z" fill="{B}"/>')
I['cartes']=svg(f'<rect x="16" y="20" width="68" height="22" rx="6" fill="{G3}"/><rect x="16" y="28" width="68" height="22" rx="6" fill="{G2}"/><rect x="16" y="36" width="68" height="22" rx="6" fill="{G1}"/><path d="M14 46 H38 Q42 46 44 50 Q50 58 56 50 Q58 46 62 46 H86 V74 Q86 82 78 82 H22 Q14 82 14 74 Z" fill="{B}"/>')
teeth=[]
for k in range(36):
    for r,da in [(42,-2.2),(42,2.2),(37,4.5),(37,7.5)]:
        a=math.radians(k*10+da); teeth.append(f'{50+r*math.sin(a):.2f},{50-r*math.cos(a):.2f}')
I['reglages']=svg(f'<polygon points="{" ".join(teeth)}" fill="{G2}"/><circle cx="50" cy="50" r="31" fill="#2b2b2b"/><circle cx="50" cy="50" r="27" fill="none" stroke="{G2}" stroke-width="3"/>'+''.join(f'<path d="M50 50 L{50+26*math.sin(math.radians(a)):.1f} {50-26*math.cos(math.radians(a)):.1f}" stroke="{G2}" stroke-width="4.5" stroke-linecap="round"/>' for a in (0,120,240))+f'<circle cx="50" cy="50" r="7" fill="{G2}"/><circle cx="50" cy="50" r="3" fill="#2b2b2b"/>')
I['tv']=svg(f'<path d="M30 39 C27 37.5 22.5 37 19.5 39.5 C15.5 43 15.5 51 18.5 57 C20.5 61 23 64 26 64 C27.5 64 28.5 63 30 63 C31.5 63 32.5 64 34 64 C37 64 39.5 60.5 41 57 C37.5 55 36.5 51 37.5 48 C38 46 39.5 44.5 40.5 43.5 C38.5 40.5 35.5 39 33 39 C31.5 39 31 39.5 30 39.5 Z M30.5 37 C30.5 33.5 32.5 31.5 35.5 31 C35.5 34 33.5 36.5 30.5 37 Z" fill="{B}"/><text x="45" y="62" font-size="30" font-weight="600" font-family="-apple-system,Jost,sans-serif" fill="{B}" letter-spacing="-1">tv</text>')
I['calculette']=svg(''.join(f'<circle cx="{26+16*c}" cy="{24+16*r}" r="6" fill="{B if c==3 else (G2 if r==0 else G3)}"/>' for r in range(5) for c in range(4)))
I['tel']=svg(f'<path d="M30 20 C26 20 22 24 22 30 C24 56 44 76 70 78 C76 78 80 74 80 70 V62 C80 59 78 57 75 56 L66 53 C63 52 61 53 59 55 L55 59 C46 54 41 49 36 40 L40 36 C42 34 43 32 42 29 L39 20 C38 17 36 15 33 15 Z" fill="{B}" transform="translate(0 4)"/>')
st=''.join(f'<line x1="{50+34*math.sin(math.radians(a)):.1f}" y1="{50-34*math.cos(math.radians(a)):.1f}" x2="{50+(30 if a%45==0 else 32)*math.sin(math.radians(a)):.1f}" y2="{50-(30 if a%45==0 else 32)*math.cos(math.radians(a)):.1f}" stroke="{G3}" stroke-width="1"/>' for a in range(0,360,9))
I['safari']=svg(f'<circle cx="50" cy="50" r="38" fill="{G1}"/><circle cx="50" cy="50" r="35" fill="#e9e9e9"/>{st}<path d="M50 50 L73 27 L54 54 Z" fill="{N}"/><path d="M50 50 L27 73 L46 46 Z" fill="{G2}"/><circle cx="50" cy="50" r="2.4" fill="{B}"/>')
I['messages']=svg(f'<path d="M50 20 C27 20 14 34 14 48 C14 57 19 64 27 69 C26 75 22 79 18 81 C26 81 33 78 37 74 C41 75 45 76 50 76 C73 76 86 62 86 48 C86 34 73 20 50 20 Z" fill="{B}"/>')
I['musique']=svg(f'<path d="M40 30 L72 22 V62" fill="none" stroke="{B}" stroke-width="6" stroke-linejoin="round"/><line x1="40" y1="30" x2="40" y2="70" stroke="{B}" stroke-width="6"/><ellipse cx="32" cy="70" rx="9" ry="7" fill="{B}" transform="rotate(-18 32 70)"/><ellipse cx="64" cy="62" rx="9" ry="7" fill="{B}" transform="rotate(-18 64 62)"/>')
I['loupe']='<svg viewBox="0 0 24 24" width="28" height="28"><path fill="currentColor" d="M15.5 14h-.79l-.28-.27A6.471 6.471 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg>'

