I['tiktok']=svg(f'<path d="M55 16 H67 C68 25 74 32 84 33 V45 C76 45 71 42 67 40 V62 C67 74 58 84 46 84 C34 84 25 75 25 63 C25 50 36 41 49 42 V54 C44 53 38 57 38 63 C38 69 42 72 46 72 C51 72 55 68 55 62 Z" fill="{B}"/>')
I['facebook']=svg(f'<circle cx="50" cy="50" r="36" fill="{B}"/><path d="M55 86 V58 H65 L67 47 H55 V40 C55 36 56 34 61 34 H67 V24 C65 24 61 23 57 23 C48 23 43 28 43 37 V47 H33 V58 H43 V86 Z" fill="#2a2a2a"/>')
